t.script:
(function(){
  var KK = document.getElementById('hh-k').getAttribute('data-k');
  /* Relais Render : page ouverte via la clé responsables, sans compte Odoo —
     /web/dataset/call_kw répond « Session expired » hors backend. */
  var RPC = 'https://ocr-pesee-webhook.onrender.com/heures/rpc';
  function rpcAction(actionId, ctx){
    return fetch(RPC,{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({action_id:actionId, ctx:ctx})});
  }
  function handleErr(d){
    var m = (d.error && ((d.error.data && d.error.data.message) || d.error.message)) || '';
    alert('Échec : ' + m);
  }
  function toDec(v){ if(!v){ return 0; } var p=v.split(':'); return parseInt(p[0]) + parseInt(p[1]||0)/60; }
  function get(week, d){
    var out = [0,0,0,0];
    week.querySelectorAll('input[data-d="'+d+'"]').forEach(function(inp){ out[parseInt(inp.getAttribute('data-f'))] = toDec(inp.value); });
    return out;
  }
  function totOf(week){
    var t = 0;
    for(var i=0;i<7;i++){ var g = get(week, i); t += Math.max(g[1]-g[0], 0) + Math.max(g[3]-g[2], 0); }
    return t;
  }
  function isTwo(card){ var c = card.querySelector('.hh-two'); return !!(c && c.checked); }
  function refresh(card){
    var two = isTwo(card);
    var wA = card.querySelector('.hh-week-0'), wB = card.querySelector('.hh-week-1');
    if(wB){ wB.style.display = two ? '' : 'none'; }
    card.querySelectorAll('.hh-wlabel').forEach(function(l){ l.style.display = two ? '' : 'none'; });
    var cp = card.querySelector('.hh-copyab'); if(cp){ cp.style.display = two ? '' : 'none'; }
    var tA = totOf(wA), tB = wB ? totOf(wB) : 0;
    var eA = wA.querySelector('[data-role="tot"]'); if(eA){ eA.textContent = (Math.round(tA*100)/100) + ' h'; }
    if(wB){ var eB = wB.querySelector('[data-role="tot"]'); if(eB){ eB.textContent = (Math.round(tB*100)/100) + ' h'; } }
    var g = card.querySelector('[data-role="totgen"]');
    if(g){ g.textContent = two ? ('Moyenne : ' + (Math.round((tA+tB)/2*100)/100) + ' h/sem (A ' + (Math.round(tA*100)/100) + ' · B ' + (Math.round(tB*100)/100) + ')')
                              : ('Total : ' + (Math.round(tA*100)/100) + ' h/sem'); }
  }
  document.addEventListener('input', function(e){
    if(e.target.matches('.hh-form input')){ refresh(e.target.closest('.hh-emp')); }
  });
  document.addEventListener('change', function(e){
    if(e.target.classList && e.target.classList.contains('hh-two')){ refresh(e.target.closest('.hh-emp')); }
  });
  document.addEventListener('click', function(e){
    var cps = e.target.closest('.hh-cpsave');
    if(cps){
      var cardc = cps.closest('.hh-emp');
      var vn = cardc.querySelector('.hh-cpn').value, vn1 = cardc.querySelector('.hh-cpn1').value;
      if(vn === '' && vn1 === ''){ alert('Saisissez au moins une valeur (N ou N-1).'); return; }
      cps.disabled = true;
      rpcAction(2021, {active_model:'hr.employee', cp_mode:1, emp_id:parseInt(cardc.getAttribute('data-emp'),10), cp_n:vn, cp_n1:vn1, hj_k:KK}).then(function(r){return r.json();}).then(function(d){
        cps.disabled = false;
        if(d.error){ alert('Échec : ' + ((d.error.data && d.error.data.message) || d.error.message)); return; }
        cps.textContent = '✓ Enregistré';
        setTimeout(function(){ cps.textContent = 'Enregistrer'; }, 2000);
      }).catch(function(){ cps.disabled = false; alert('Échec réseau'); });
      return;
    }
    var ed = e.target.closest('.hh-edit');
    if(ed){
      var card0 = ed.closest('.hh-emp');
      var f = card0.querySelector('.hh-form');
      f.style.display = (f.style.display === 'block') ? 'none' : 'block';
      refresh(card0);
      return;
    }
    var b = e.target.closest('.hh-b[data-act]');
    if(!b){ return; }
    var card = b.closest('.hh-emp');
    var act = b.getAttribute('data-act');
    if(act === 'lundi' || act === 'clear'){
      var week = b.closest('.hh-week');
      if(act === 'lundi'){
        for(var f2=0; f2<4; f2++){
          var src = week.querySelector('input[data-d="0"][data-f="'+f2+'"]').value;
          for(var d=1; d<=4; d++){ week.querySelector('input[data-d="'+d+'"][data-f="'+f2+'"]').value = src; }
        }
      } else {
        week.querySelectorAll('input').forEach(function(i){ i.value=''; });
      }
      refresh(card);
      return;
    }
    if(act === 'copyab'){
      var wA = card.querySelector('.hh-week-0'), wB = card.querySelector('.hh-week-1');
      for(var d3=0; d3<7; d3++){
        for(var f3=0; f3<4; f3++){
          wB.querySelector('input[data-d="'+d3+'"][data-f="'+f3+'"]').value =
            wA.querySelector('input[data-d="'+d3+'"][data-f="'+f3+'"]').value;
        }
      }
      refresh(card);
      return;
    }
    if(act === 'save'){
      var two = isTwo(card);
      var wA2 = card.querySelector('.hh-week-0'), wB2 = card.querySelector('.hh-week-1');
      var horA = [], horB = [];
      for(var d4=0; d4<7; d4++){ horA.push(get(wA2, d4)); horB.push(get(wB2, d4)); }
      if(totOf(wA2) <= 0){ alert('Renseignez au moins une plage horaire en semaine A.'); return; }
      if(two && totOf(wB2) <= 0){ alert('Le cycle 2 semaines est coché : renseignez aussi la semaine B (ou utilisez « A → B »).'); return; }
      b.disabled = true;
      var ctx = {active_model:'hr.employee', emp_id:parseInt(card.getAttribute('data-emp')),
                 horaires:horA, horaires_b:horB, deux_semaines:two, hj_k:KK};
      rpcAction(2021, ctx).then(function(r){return r.json();}).then(function(d){
        b.disabled = false;
        if(d.error){ handleErr(d); return; }
        var res = d.result || {};
        alert('✓ Horaire enregistré pour ' + card.getAttribute('data-name') + '\n' +
              (res.deux ? ('Cycle 2 semaines — moyenne ' + (res.semaine||0).toFixed(2) + ' h/sem')
                        : ((res.total||0).toFixed(2) + ' h/sem')));
        location.reload();
      }).catch(function(){ b.disabled = false; alert('Échec réseau'); });
    }
  });
})();
